attempts.query:
PREFIX afiliaciones: <https://w3id.org/rastro/afiliaciones#>
SELECT (COUNT(DISTINCT ?pub) AS ?publicaciones)
WHERE {
  ?id a afiliaciones:Identification ;
      afiliaciones:identifies <https://ror.org/03cqe8w59> ;
      afiliaciones:ofMention ?m .
  ?m afiliaciones:inPublication ?pub .
}
